INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','حجم غلة السبانخ في الهكتار بنظام الري بالتنقيط: دليل شامل لزيادة الإنتاجية' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على طرق لرفع إنتاجية السبانخ في الهكتار باستخدام تقنية الري بالتنقيط (التساقط) بفعالية. دليل شامل من أفبا (AFP) يغطي تفاصيل تقنية الري بالتنقيط لزيادة الغلة.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
