INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Фаҳмед, чӣ тавр ҳаҷми ҳосили сабзадорӣ (спинач) дар ҳар ҳектарро бо истифода аз усули нақши Тип зиёд кардан мумкин аст. Ин раҳнамои пурра дастурҳои амалӣ барои зиёд кардани самаранокӣ ва самаранокии кишоварӣ-иқтисодиро пешниҳод мекунад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
