INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل عملي للمزارعين لإدارة الآفات وأمراض العدس في أنظمة الري بالتنقيط. تقنيات AFP، مكافحة متكاملة، وحلول مستدامة لحقلك في العراق.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
