INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Лӯбӯ яке аз муҳимтарин ҳобҳо дар саноати кишоварӣ мебошад, ки бо вуҷуди муқовимати нисбии он ба хушкӣ, ҳассосияти махсусро ба намии нисбии баланди сатҳи хок ва ҳамчунин пӯшиш (canopy)-и растани дорад. Тағйир аз оварии сатҳии анъанавӣ ба <strong>оварии қатрагӣ</strong> ё <strong>нишоки бӯзӣ (nibar)</strong>, танҳо усули ҳаҷҳеҷкунии таҳсилот барои партоб нашуда, балки чигеркараи идоракунии қавитар барои назорат <strong>зарароварон ва бемориҳои лӯбӯ</strong> мудоро мешуморанд. Дар ин қисм, ба таҳлили амиқтари ин масъала мепардозем, ки чӣ тавр идоракунии дақиқи намии хок, паҳншавии бемориҳоро зери назорат мебарад. Принсипҳои техникии насб ва нигоҳдории системаҳо, асоси аслии ин идоракуни аст.</p>\n<h2>Таъсири оварии қатрагӣ ба муҳити растани лӯбӯ</h2>\n<p>Растани лӯбӯ ҳассосияти баланди бемориҳои қорӣ ва бактериявиро дорад, хусусан дар шартҳое, ки намии сатҳи хок дар давомии дароз баланд бошад. Дар оварии қатрагӣ, об танҳо ба решаҳои растани ва нишоки бӯзӣ дар атрофи буттаҳо ворид карда мешавад. Ин усул боиси он мегардад, ки сатҳи хок байни сатрҳо хушк боқадад. Намии нисбии камтар дар сатҳи хок, монеаи ҳосили шартҳои мусоид барои рушди пӯсидагии решаи сарма ва бемориҳои хокӣ мешавад. Бинобар ин, <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">насби дурусти нишоки бӯзӣ</a> нақши ҳайатиро дар шарҳи дақиқи ин соҳаи намнок иҷро мекунад, то аз чуншудагии зиёди баргҳо ё решаи сарма пешгирӣ шавад. Паҳншавии дурусти нишок ба муҳити решафшонӣ, калиди муваффақият дар ин марҳила аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-عدس-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های عدس با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation лӯбӯ</figcaption></figure>\n<h2>Идоракунии бемориҳои қорӣ тавассути назорати намӣ</h2>\n<p>Бемориҳое, монанди Rust (Рангкушӣ) ё Рӯзбӯри, дар лӯбӯ, гарчанде ки аксар вақт тавассути ҳаво интиқол меёбанд, аммо рушд ва шиддати онҳо ба қатъӣ ба намии мавҷуда дар муҳити зарраи растани алоқаманд аст. Бо истифода аз системаи қатрагӣ, намии нисбии маҳаллӣ дар атрофи пояи растани кам мешавад. Ин кор бевосита бо камшавии фаъолияти қорӣ, ки ба ҳосили бемориварии спораҳои худ ниёз доранд, ҳамроҳ аст. Кишоварон метавонанд бо танидани фосилаҳои оварӣ, ба тавре ки сатҳи хок ҳамеша гардак нашавад, аз пашидиши бемориҳои хокӣ монанди Fusarium, ки сабаби зараровари решаи лӯбӯ аст, пешгирӣ кунанд. Идоракунии дақиқи таъминот низ тавассути оварии қатрагӣ (Фертигация) имконпазир мешавад, ки бо зиёдшавии бехаттарии растани, муқовимати систематӣ (ISR)-ро дар муқобили зарароварон мустаҳкам мекунад. Барои фаҳмиши беҳтари иртиботи байни идоракунии кишоварӣ ва маҳсулот, таҳқиқидани дастураи <a href="https://navar-abyari.ir/garlic-yield-per-hectare-factors-increase-36780-2/"> зиёд кардани ҳосили сир дар гектар</a> метавонад намунаҳое-ро пешниҳод кунад, ки ба ҳобҳои дигар интиқолотиш мумкин аст.</p>\n<h2>Нақси бехатрии хок дар кам кардани зарароварони реша</h2>\n<p>Яке аз чорамҳои асосӣ дар боғҳои лӯбӯ, мавҷудияти зарароварони решагӣ монанди инҳоро ва коми хакҳо аст. Оварии қатрагӣ бо сабаби марказгирии оварӣ дар зони реша, метавонад аз паҳншавии баъзе зарароварони сатҳӣ, ки ба муҳити умумии намнок ниёз доранд, пешгирӣ кунад. Инчунин, истифода аз чорамҳои қатрагӣ барои ворид кардани моддаҳои ҷозиб кардани зарароварон ё биологӣ ба реша, метавонад бо мақсади дақиқ ба назорати зарароварони зери хок кӯмак расонад. Агар хоҳишед фаҳмиши беҳтареро дар бораи сохтори тасмими худ дошта бошед, ба мақолаҳои алоқамандро <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">Нирӯгирии лентаи капилярӣ</a> Барои гирифтани нигарониши умумӣ аз таъсири идоракунӣ бар самаранокии ҳосил, таваҷҷӯҳ диҳед. Фаҳмиши раванди пайвастшавии лента ба заминаи хокӣ кафилятдиҳандаи пурраи тақсимоти баробари об аст.</p>\n<h2>Ҳашароти зараровар ва идоракунии таҳсилоти онҳо</h2>\n<p>Ҳатми, ки обёрӣи қатрагӣ баррасиҳо ҳашаротро нест мекунад, вай тағйироти режими обёрӣ метавонад нақши муҳоҷирати баъзе ҳашароти зарароварро тағйир диҳад. Баъзе ҳашароти зараровар ва мӯрҳои сафед майл доранд ба минтақаҳои намнаки худии хок. Бо нигоҳ доштани хушкнии нисбӣ байни сатҳҳо, зичии ин ҳашароти зараровар дар сатҳи хок кам мешавад. Илова бар ин, кам шудани намӣи атроф бошакҳо, фаъолияти паразиткунандагонро (Parasitoids) аз ҷиҳати устувории зистгоҳи онҳо тақвият медиҳад. Идоракунии таркибии ҳашароти зараровар (IPM) дар системаҳои қатрагӣ бояд бо ғамхорӣ ба саломати умумии наботот оғоз шавад; набототе, ки зери стресси камобӣи шадид ё оби зиёдатӣ (Waterlogging) нест, ба муқовамоти дифоӣи худ беҳтар ҷавоб медиҳад. Шинохси дақиқи навъҳои ҳашароти зараровар қадами аввал барои муқовимат ба онҳост.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-عدس-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های عدس با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation чина</figcaption></figure>\n<h2>Нуқтаҳои амалӣ барои деҳқон дар қисмҳои чина</h2>\n<p>Барои бархӯрд аз файдаҳои обёрӣи қатрагӣ дар муқоимат бо ҳашароти зараровар ва бемориҳои чина, риояи нуқтаҳои зерин зарур аст:</p>\n<ul>\n  <li><strong>Интихоби диаметр ва фосилаи лента/қатра:</strong> Фосила байни қатраҳо бояд бо андозаи решаи чина мувофиқ бошад. Решаи чина чуқур нест, бинобар ин система бояд чунин бошад, ки намииро дар 20 то 30 сантиметри аввали хок марказ мекунад.</li>\n  <li><strong>Истифодаи филтри дақиқ:</strong> Илтиҳобҳои микробӣ дар об тавассути лентаи капилярӣ ба хок ворид мешаванд. Истифодаи филтрҳои дақиқ (Fine Mesh) ё дискҳо барои пешгирии маҳкам шудани қатраҳо ва интиқоли бемориҳои обӣ зарур аст.</li>\n  <li><strong>Анҷоми фортifikasi (Fertigation):</strong> Таззӣ тавассути қатра, имкони омодагидории маводди зидди қарази хокӣ ё ҳашароткушҳои системӣро фароҳам меорад. Барои маълумоти бештар дар бораи таҷҳизоти иловагӣ, <a href="https://navar-abyari.ir/tips-before-buying-drip-tape-irrigation-iq/">Нуқтаҳо пеш аз харидани лентаи қатрагӣ</a> ро таҳқиқ кунед. Санҷиши сифати маводи лента, пеш аз харидан, аз рафъи сармоя пешгирӣ мекунад.</li>\n  <li><strong>Дурӣ аз боди намдар будани баргҳо:</strong> Дар сурати истифодаи лентаи капилярӣ, боварӣ ҳосил кунед, ки лента дақиқан зери сояи наботот ҷойгир шудааст, то намӣ ба баргҳо, ки моддаи бардоштани паллокидҳо мебошанд, нарасад.</li>\n</ul>\n<h3>Ҷадвали тайёркунии баррасӣ барои бемориҳои маъмул</h3>\n<table>\n  <thead>\n    <tr>\n      <th>Марҳилаи рушд</th>\n      <th>Беморӣ/Афатҳои ҳадафӣ</th>\n      <th>Таъсири ороиши танқатрӣ</th>\n      <th>Даракчаи идоракунӣ</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>Дарунҷонидан</td>\n      <td>Таваллӯни бобуна ва ниҳолҳо</td>\n      <td>Кам кардани хавф аз сабаби хушкӣ байни сатҳҳо</td>\n      <td>Коркарда бобунае тозакардашуда, ороиши сабук ва давомдор</td>\n    </tr>\n    <tr>\n      <td>Рушди вегатативӣ</td>\n      <td>Акант (Eunagi), таваллӯни пойгоҳӣ</td>\n      <td>Идоракунии намии маҳаллӣ, кам кардани паҳншавии таваллӯн</td>\n      <td>Моҳибозии бозорӣ зерини бутта, истифодаи моддаҳои биологиказии заминӣ</td>\n    </tr>\n    <tr>\n      <td>Данедодан</td>\n      <td>Пестикобиӣ (Rust)</td>\n      <td>Кам кардани намии нисбии маҳаллӣ, кам кардани шиддати спорабардорӣ</td>\n      <td>Кушодани мусоити ороиш пеш аз буридани дона барои сахт шудани дона, хориҷ кардани қалмои растании</td>\n    </tr>\n  </tbody>\n</table>\n<p>Лозим аст диққат додан, ки системаи ороиши танқатрӣ танҳо як табобат нест, балки як пешгирӣ аст. Хориҷ кардани қалмои бобуна аз майдон ва барориши муносиби майдон ду омили асосӣ мебошанд, ки бо ороиши танқатрӣ чархаи ҳаёти беморро меварзад. Дар минтақаҳои бароридишударо, омехтакунии ороиши танқатрӣ бо ислоҳи замин метавонад таъсирҳои табобатӣи зиёдро дошта бошад. Фаҳмиши принсипҳои ороиши дигар маҳсулоти кишоварзӣ, ба монанди роҳнамои ороиши шитобӣ барои турпа, метавонад нуқтаи назари қимматӣ оид ба мутобиқсозии техникии системҳо ба донишҳои гуногуни растании пешниҳод кунад.</p>\n<h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2>\n<ol>\n  <li><strong>Оё оҳноксозии қатқати ба баланд шудани нархи ниҳоии маҳсулот оварда мерасонад?</strong><br>Наҳ, ҳатман. Гарчанде ки ҳамоиши аввалияи таҷҳизот баландтар аст, аммо хароҷоти доруҳои қорубравар, иловаи об ва ҳамоиши қатқати кам мешавад. Инчунин, сифати беҳтари маҳсулоти ба даст омада аз рӯи камшавии бемориҳои хокӣ метавонад ба зиёд шудани талаботи бозор ва нархи фурӯш оварда расонад.</li>\n  <li><strong>Каи як анвои филтр барои нонушӣ (адул) тавсия дода мешавад?</strong><br>Адул решаҳои бофтарок дорад ва нуҳони қатқати ҳамчунин сӯрохҳои хурд дорад. Тавсия дода мешавад, ки аз филтрҳои дискии бо зичии 60 то 120 ё филтрҳои шабакавии 120 сӯрох дар инч истифода барад, то аз дохилшавии зарраҳои хурд ба дохили система пешгирӣ карда шавад.</li>\n  <li><strong>Оё метавон инҳебкунандаи оҳуро бо роҳи қатқати ҳамчун идоракунии пешгирикунанда истифода бард?</strong><br>Истифодаи қатқати барои идоракунии оҳурон (Herbicide) хеле хатарнок аст ва метавонад ба растр асосӣ зарари ҷиддӣ расонад. Идоракунии оҳурон бояд бо усулҳои механикӣ ё пратсини мақсаднок сатҳӣ амалӣ карда шавад, на бо роҳи қатқати.</li>\n  <li><strong>Таъсири оҳноксозии қатқати ба хок ва хурдукаҳо чӣ гуна аст?</strong><br>Хурдукаҳои фоидаовари хокӣ, ки ба хоки тар вобастаанд, метавонанд дар минтақаҳои хушк байни нуқтаҳои қатқати камтар фаъол бошанд. Ин метавонад мувозунати микроби хокиро тағйир диҳад. Назорати доимии саломати хок барои ҷуброни ин таъсир тавсия дода мешавад. Барои фаҳмиши беҳтари идоракунии деҳқони, шумо метавонед аз роҳнамои <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">Насби нуҳони қатқати</a> барои беҳтар кардани шартҳои хок истифода баред.</li>\n</ol>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-عدس-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های عدس با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation адул</figcaption></figure>\n<h2>Хулоса ва тавсияи ниҳоӣ</h2>\n<p>Guзарониши адул аз оҳноксозии классикӣ ба системҳои қатқати ё нуҳони қатқати яке аз муқаррароти оқилона барои идоракунии <strong>зараррасандагон ва бемориҳои адул</strong> ҳисобида мешавад. Бо кам шудани рутубати сатҳӣ, кам шудани стресси биологии растр ва имконияти идоракунии дақиқтарши ғизои, деҳқон як қабати дифоили пинҳонро барои ҳимоят аз бемориҳои хокӣ ва қорӣ ба вуҷуд меорад. Бо вуҷуди ин, ин технология бояд дар паҳлӯи дониши деҳқонии маҳаллӣ ва назорати дақиқ аз ҷониби мутахассиси растанишиносӣ иҷро шавад. Азбаски сифати системаи оҳноксозӣ бевосита ба саломати маҳсулот таъсир мерасонад, ҳатман дар марҳилаҳои насб ба тафсилоти техникӣ диққат диҳед. Барои ошноӣ бо усулҳои дурусттари насб, муроҷиат ба матлаоти ихтисоси чунин <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">Насби нуҳони қатқати</a> тавсия дода мешавад. Дар охир, тайёрӣ ба системҳои равои омодакунии рутубати хок метавонад давраҳои оҳноксозиро беҳтар намояд ва дар тӯли муддати тӯлонӣ, хатарро барои бемориҳоро ба ҳадди акам расонад. Ошноӣ бо манбаъҳои об ва идоракунии боронҳо низ метавонад ба фаҳмиши амиқтар чархҳо об дар деҳқони оварда расонад, ҳамон тавре ки дар мақолаҳо чун <a href="https://navar-abyari.ir/gafsii-devori-lentai-obyorii-qatragi/">Микдорҳои оҳноксозии нуҳони қатқати</a> Пешниҳод карда шуд.</p>','Идоракунии зарароварҳо ва бемориҳои нухур дар системҳои обёрӣ бозгаштнок: Раҳнамои ҷамъиятӣ барои деҳқонон','Ин мақола шарҳ меди, ки чӣ тавр обёрӣи бӯдакӣ (дампа) метавонад нақши ҳалкунанда дар кам кардани хатарҳои рушди зараррезҳо ва бемориҳои қарзӣ ва бактериявӣ дар нули нашоқӣ бозӣ кунад. Бо дидан принсипҳои техникӣ, аз интихоби таҷҳизот то реҷаи обёрӣ, чӣ тавр идоракунии кишт ва ғалладаро беҳтар карданро барои ҳосили саломаттар ёд гиред.','publish','closed','closed','idorokunii-zarorovarmo-va-bemorihoi-nuhur-dar-systemahoi-obori-bozgashtnak',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
